// Hora actual en España (Europe/Madrid, gestiona horario de verano/invierno)
const now = new Date();
const parts = Object.fromEntries(
  new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/Madrid',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', weekday: 'short', hour12: false
  }).formatToParts(now).map(p => [p.type, p.value])
);

const hour = parseInt(parts.hour, 10) % 24;
const minute = parseInt(parts.minute, 10);
const weekdayMap = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 };
const weekday = weekdayMap[parts.weekday];
const diasEs = ['', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];

// ===== FESTIVOS (formato MM-DD) - editar aquí =====
const FESTIVOS_FIJOS = {
  '01-01': 'Año Nuevo',
  '01-06': 'Reyes',
  '05-01': 'Día del Trabajo',
  '08-15': 'Asunción',
  '09-08': 'Festivo local',
  '09-11': 'Diada de Catalunya',
  '10-12': 'Fiesta Nacional',
  '11-01': 'Todos los Santos',
  '11-29': 'Festivo local',
  '12-06': 'Constitución',
  '12-08': 'Inmaculada',
  '12-25': 'Navidad'
};
// Festivos puntuales de un año concreto (formato YYYY-MM-DD), ej: '2027-03-19': 'Traslado'
const FESTIVOS_EXTRA = {};

// Viernes Santo (móvil, calculado a partir de Pascua)
function viernesSanto(y) {
  const a = y % 19, b = Math.floor(y / 100), c = y % 100, d = Math.floor(b / 4), e = b % 4;
  const f = Math.floor((b + 8) / 25), g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30, i = Math.floor(c / 4), k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7, m = Math.floor((a + 11 * h + 22 * l) / 451);
  const mes = Math.floor((h + l - 7 * m + 114) / 31), dia = ((h + l - 7 * m + 114) % 31) + 1;
  const vs = new Date(Date.UTC(y, mes - 1, dia - 2));
  return `${String(vs.getUTCMonth() + 1).padStart(2, '0')}-${String(vs.getUTCDate()).padStart(2, '0')}`;
}

const year = parseInt(parts.year, 10);
const mmdd = `${parts.month}-${parts.day}`;
const festivo = FESTIVOS_EXTRA[`${year}-${mmdd}`] || FESTIVOS_FIJOS[mmdd] || (mmdd === viernesSanto(year) ? 'Viernes Santo' : null);

// Laborable: lunes a viernes de 08:00 a 12:59 (cierra a las 13:00), excepto festivos
const minutos = hour * 60 + minute;
const esLaborable = !festivo && weekday >= 1 && weekday <= 5 && minutos >= 8 * 60 && minutos < 13 * 60;

const fecha = `${parts.day}/${parts.month}/${parts.year}`;
const hora = `${String(hour).padStart(2, '0')}:${parts.minute}`;

const vars = {
  horario_laboral: esLaborable ? 'si' : 'no',
  es_festivo: festivo ? 'si' : 'no',
  festivo: festivo || '',
  fecha_actual: fecha,
  hora_actual: hora,
  dia_semana: diasEs[weekday]
};

// Formato válido tanto para el Inbound Call Webhook de Retell
// (call_inbound.dynamic_variables) como para una Custom Function (campos raíz)
return [{ json: { call_inbound: { dynamic_variables: vars }, ...vars } }];
